<script setup lang="ts">import{ref,onMounted}from'vue';import{useRoute}from'vue-router';import{get}from'../services/api';import EquityChart from'../components/charts/EquityChart.vue';const route=useRoute(),d=ref<any>({reports:[],trades:{data:[]},equity:[]});onMounted(async()=>d.value=await get(`/backtests/${route.params.id}/report`))</script><template><q-page padding><div class="page-title"><h1>Backtest Report</h1><q-badge>OUT-OF-SAMPLE clearly separated</q-badge></div><EquityChart :points="d.equity"/><q-table flat bordered :rows="d.trades?.data||[]" row-key="id"/><pre class="report">{{JSON.stringify(d.reports,null,2)}}</pre></q-page></template>
